INSERT INTO `t_materiel` VALUES (1,'M-GSO-U','Module de réception pour sondes GemSense One USB','USB\r\nLed d’activité\r\nAlimentation sur secteur','GSO','RADIO',NULL),(2,'M-GSO-E','Module de réception pour sondes GemSense One Ethernet','Ethernet RJ 45\r\nLed activité\r\nAlimentation sur secteur','GSO','RADIO',NULL),(3,'GSO-IT','Gemsense One Température interne','Fréquence de mesure 15 min fixe \r\nFonction mémoire (700 valeurs)\r\nPiles AAA*2 (2 ans selon utilisation)\r\nTempérature d\'utilisation : -20°C à 40°C','GSO','RADIO',NULL),(4,'GSO-ITH','Gemsense One Température & humidité interne','Fréquence de mesure 15 min fixe \r\nFonction mémoire (700 valeurs)\r\nPiles AAA*2 (2 ans selon utilisation)\r\nTempérature d\'utilisation : 10°C à 40°C\r\nDomaine d\'utilisation : 10%Hr à 90%Hr ','GSO','RADIO',NULL),(5,'GSO-ET','Gemsense One Température externe','Fréquence de mesure 15 min fixe \r\nFonction mémoire (700 valeurs)\r\nPiles AAA*2 (2 ans selon utilisation)\r\nProtection : inox 316 L Ø 6 x 40 mm\r\nTempérature d\'utilisation : -40°C à 125°C','GSO','RADIO',NULL),(6,'GSO-ETH','Gemsense One Température & humidité externe','Fréquence de mesure 15 min fixe \r\nFonction mémoire (700 valeurs)\r\nPiles AAA*2 (2 ans selon utilisation)\r\nTempérature d\'utilisation : 10°C à 80°C\r\nDomaine d\'utilisation : 10%Hr à 90%Hr ','GSO','RADIO',NULL),(7,'M-GSP','Module de réception pour sondes GemSense Pro Ethernet','Interface 10Base-T ou 100Base-TX\r\nConnecteur RJ45\r\nLed Link & activité\r\nSécurisé par mot de passe\r\nCPU : DSTni-EX\r\nMémoire : 256k SRAM 512Kb flash\r\nAlimentation sur secteur','GSP','RADIO',NULL),(8,'GSP-RN-BL','Gemsense Pro Numérique blanc','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 125°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 125 °C Câble long 3 m BLANC','GSP','RADIO',NULL),(9,'GSP-RN-GR','Gemsense Pro Numérique gris','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 70°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 70 °C  Câble long 3 m GRIS PLAT','GSP','RADIO',NULL),(10,'GSP-RP','Gemsense Pro platine','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nGaine de protection : acier inox 316 L, Ø 6 \r\nTempérature d\'utilisation : -200 à 200°C\r\nSonde : Pt 100 céramique CEI 60751 classe A, en montage 4 fils\r\nCâble de raccordement : PFA/PFA ','GSP','RADIO',NULL),(11,'GSP-RP-ALIM','Gemsense Pro platine alimentaire','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nGaine de protection : acier inox 316 L - Ø 5 mm, \r\nlongueur utile : 150 mm\r\nPoignée : surmoulée silicone THT 250 °C - couleur rouge brique, longueur 130 mm\r\nSonde : Pt1000 céramique DIN IEC 60751 classe B, simple en montage A\r\nCâble de raccordement : silicone atoxique THT 250 °C continu - Alimentaire couleur rouge brique\r\nTempérature d\'utilisation : -50 à + 250 °C','GSP','RADIO',NULL),(12,'GSP-RP-CONT','Gemsense Pro platine contact','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur de température\r\nSonde : Pt 100 CEI 60751 classe A, \r\nsimple enroulement, élément de mesure couche mince sous rétractable PFA\r\nSous film polyester \r\nTempérature d\'utilisation : -80+160 °C\r\nFixation par colle silicone sur surface dégraissée\r\nCâble de raccordement : PFA/PFA, section 0,09 mm², longueur 2 mètres, 3 conducteurs','GSP','RADIO',NULL),(13,'GSP-RP-AU','Gemsense Pro platine autoclave','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur de température\r\nGaine de protection : acier inox 316 L - Ø 6 x 200 mm, \r\nprolongée par câble PFA/silicone protégé par flexible inox Ø 7 mm, longueur 1,5 mètres puis gaine étanche Ø 6 x 100 mm pour passage de cloison\r\nSonde : Pt 100 céramique CEI 60751 classe A, simple ou double enroulement en montage 3 fils\r\nCâble de raccordement : PFA/silicone, longueur 2 mètres\r\nTempérature maximale d\'utilisation : +180 °C\r\nExécution étanche','GSP','RADIO',NULL),(14,'GSP-RP-CF','Gemsense Pro platine chambre froide','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur de température\r\nCapteur muni à l\'extrémité d\'une ogive inox diamètre 6 mm \r\nsertie sur 15 mètres de câble silicone.\r\nConfiguration 3 fils\r\nElément sensible Pt100 suivant NF EN 60751 classe B\r\nOgive inox diamètre 6 mm, longueur 50 mm\r\nTempérature d\'utilisation : -50°C à + 100°C\r\nSortie sur 15 mètres de câble : Conducteurs souples 7 brins \r\nde ø 0.2 mm isolés PFA sous gaine caoutchouc de silicone. \r\n2 conducteurs rouges, 1 conducteur blanc','GSP','RADIO',NULL),(15,'GSP-RP-MICRO','Gemsense Pro platine micro-capteur','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur de temperature platine\r\nCapteur micro ø 2,18mm L 4,75m : -70°C à + 250°C','GSP','RADIO',NULL),(16,'GSP-RQ-CO2','Gemsense Pro CO2','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nGamme pro avec portée étendue\r\nLe capteur de dioxyde de carbone Vaisala CARBOCAP® GMP251 est une sonde intelligente et autonome.\r\nLa plage de température de fonctionnement va de -40 à +60 °C, \r\net la plage de mesure est comprise entre 0 et 20 % de CO2\r\nLe capteur GMP251 fait appel à la technologie unique de deuxième génération Vaisala CARBOCAP® qui offre une stabilité exceptionnelle. \r\nLa durée de vie de la GMP251 est prolongée grâce à un nouveau type de source de lumière infrarouge (IR) qui remplace l\'ampoule à incandescence traditionnelle. Elle bénéficie de compensations complètes de température et de pression de la mesure du COCO2 - mesure de température intégrée pour la compensation. ','GSP','RADIO',NULL),(17,'GSP-RQ-HYG','Gemsense Pro hygrométrie','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nGamme pro avec portée étendue\r\nPlage de mesure de 0% à 100 %hr\r\nTempérature d\'utilisation de 10°C à +60°C\r\nCapteur de diamètre 12 mm longueur 71 mm','GSP','RADIO',NULL),(18,'GSP-RQ-THE','Gemsense Pro thermocouple','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nCapteur de température\r\nCapteur thermocouple J chemise (déformable) :\r\nø 3 mm longueur 50 cm\r\nTempérature d\'utilisation  : 100°C à + 1500°C\r\nSortie sur câble tresse inox 1m','GSP','RADIO',NULL),(19,'GSP-RQ-PRES','Gemsense Pro pression différentielle','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur de pression \r\nCapteur piézoélectique\r\nDomaine d\'utilisation  : 0 à 250 Pa\r\nSortie sur câble tresse inox 1m','GSP','RADIO',NULL),(20,'GSP-RQ-ATMO','Gemsense Pro pression atmosphérique','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur de pression  \r\nCapteur ratiométrique\r\nDomaine d\'utilisation : atmosphère ambiante','GSP','RADIO',NULL),(21,'GSP-RQ-LUM','Gemsense Pro lumière','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur de lumière \r\nCapteur photorésistif\r\nDomaine d\'utilisation : lumière ambiante','GSP','RADIO',NULL),(22,'GSP-RQ-01V','Gemsense Pro 0-1 Volt','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur de tension \r\nEntrée 0-1Volt','GSP','RADIO',NULL),(23,'GSP-RQ-420MA','Gemsense Pro 4-20 mA','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur de courant \r\nEntrée 4-20mA','GSP','RADIO',NULL),(24,'GSP-RQ-NONF','Gemsense Pro NO NF','Sonde GemSense Pro avec écran 2,9\" \r\nFonction mémoire (5300 valeurs)\r\nBatterie de secours (10 jours)\r\nGamme pro avec portée étendue\r\nCapteur TOR \r\nEntrée récuperation de contact NO ou NF\r\nDomaine d\'utilisation : reprise de contact','GSP','RADIO',NULL),(25,'GSP-RP-ETAL','Gemsense Pro Etalon','Sonde GemSense Pro avec écran 2,9\" \r\nLecture écran sous forme de liste pour des étalonnages \r\nplus faciles\r\nBatterie de secours (15 jours)\r\nGamme pro avec portée étendue\r\nGaine de protection : acier inox 316 L, Ø 3,5 longueur utile 150 mm \r\nTempérature d\'utilisation : -200 à 200°C\r\nSonde : Pt 100 céramique CEI 60751 classe 1/3DIN, \r\nen montage 4 fils\r\nCâble de raccordement : PFA/PFA \r\nRésolution d’affichage : 0,01°C \r\nRésolution de mesure : 0,003°C','GSP','ETALON',NULL),(26,'GSP-XN-BL','Gemsense Pro Ethernet numérique blanc','Liaison Ethernet RJ45 \r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 125°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 125 °C | Câble long 3 m BLANC','GSP','ETHERNET',NULL),(27,'GSP-XN-GR','Gemsense Pro Ethernet numérique gris','Liaison Ethernet RJ45 \r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 70°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 70 °C | Câble long 3 m GRIS PLAT','GSP','ETHERNET',NULL),(28,'GSP-XP','Gemsense Pro Ethernet platine','Liaison Ethernet RJ45 \r\nGaine de protection : acier inox 316 L, Ø 6 \r\nTempérature d\'utilisation : -200 à 200°C\r\nSonde : Pt 100 céramique CEI 60751 classe A, en montage 4 fils\r\nCâble de raccordement : PFA/PFA ','GSP','ETHERNET',NULL),(29,'M-GSP-F','Module de réception pour sondes GemSense Pro Filaire','Ethernet RJ 45\r\nLed activité\r\nAlimentation sur secteur','GSP','FILAIRE',NULL),(30,'M-GSP-F-ALS','Alimentation supplémentaire pour sondes GemSense Pro Filaire','','GSP','FILAIRE',NULL),(31,'GSP-FN-BL','Gemsense Pro filaire numérique blanc','Bus d’alimentation de data RS485\r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 125°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 125 °C | Câble long 3 m BLANC','GSP','FILAIRE',NULL),(32,'GSP-FN-GR','Gemsense Pro filaire numérique gris','Bus d’alimentation de data RS485\r\nCapteur numérique\r\nTempérature d\'utilisation : -30°C à 70°C\r\nCapteur numérique Ø 6mm l, 50mm  / -30°C à 70 °C | Câble long 3 m GRIS PLAT','GSP','FILAIRE',NULL),(33,'GSP-FP','Gemsense Pro Filaire platine','Bus d’alimentation de data RS485\r\nGaine de protection : acier inox 316 L, Ø 6 \r\nTempérature d\'utilisation : -200 à 200°C\r\nSonde : Pt 100 céramique CEI 60751 classe A, en montage 4 fils\r\nCâble de raccordement : PFA/PFA ','GSP','FILAIRE',NULL);

